#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Run the migration model on a NOR fixture generated by Studio Tess .3.
The matching state vector is from its last saved slot; the first track's
OUTSIDE setting was 20..23 for slots A..D. The C test injects interrupted
writes, verifies each complete block and checks that retry is idempotent.
"""
from pathlib import Path
import gzip
import subprocess
import sys
import tempfile
root = Path(__file__).resolve().parent
with tempfile.TemporaryDirectory(prefix="studio-upgrade-") as tmp:
    nor = Path(tmp) / "studio3.nor"
    nor.write_bytes(gzip.decompress((root / "fixtures/studio-tess3.nor.gz").read_bytes()))
    subprocess.run([str(Path(sys.argv[1]).resolve()), str(nor), str(root / "fixtures/studio-tess3-state.bin")], check=True)
